/**
 * Rule ids that only ever reach a finding through `Issue.rule`.
 *
 * Some emitters key the finding on a broad `code` and narrow it with a
 * per-defect `rule` — `tddList.ts` raises one code but tags each finding
 * `TDDLIST-003` / `TDDLIST-004`. A waiver may name either, so the ids that
 * never appear as a `code` are listed here rather than folded into
 * {@link EMITTED_RULE_CODES}: they are waivable, but they are not codes.
 */
export const RULE_ID_ALIASES: readonly string[] = [
  "TDDLIST-001",
  "TDDLIST-002",
  "TDDLIST-003",
  "TDDLIST-004",
  "WAIVER-001",
  "WAIVER-002",
  "WAIVER-003",
  "WAIVER-004",
  "WAIVER-005",
];

/**
 * Codes emitted from `src/cli/`, after `applyWaivers` has run.
 *
 * They are deliberately NOT in {@link EMITTED_RULE_CODES}: a waiver naming one
 * can never match a finding, and registering them would let an unmatchable
 * waiver be reported as `active`. But they DO exist, and calling them unknown
 * rules sent an operator looking for a typo — so `applyWaivers` uses this list
 * to say the true thing instead: the rule exists and no waiver can suppress it,
 * because it is appended after waiver processing.
 */
export const POST_WAIVER_RULE_CODES: readonly string[] = [
  "QFAI-PROFILE-001",
  "QFAI-SCAN-001",
  "QFAI-SCAN-002",
];
